new="await page.locator('[data-brain-preset=\"always-right\"]').click();assert.equal(await page.locator('#to-setup').isDisabled(),false,'terminal REPEAT preset stays runnable without a dead continuation');assert.equal(await page.locator('#brain-graph .brain-trigger-chip').count(),6,'collision-ready preset keeps six real entry triggers in the hub');assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),4,'preset body stays compact after trigger infrastructure is projected into the hub');await page.locator('#to-setup').click();assert.equal(await page.locator('#top-status').textContent(),'SETUP');assert.equal(await page.locator('[data-scenario]').count(),2,'SETUP exposes two objectives over the same core loop');assert.equal(await page.locator('#scenario-title').textContent(),'КРИТИКА ИДЕИ');assert.match(await page.locator('#scenario-objective').textContent(),/СОХРАНИТЬ КОНТАКТ/);assert.match(await page.locator('#scenario-end').textContent(),/20 РАУНДОВ/);await page.locator('[data-scenario=\"direct-answer\"]').click();assert.equal(await page.locator('#scenario-title').textContent(),'НЕУДОБНЫЙ ВОПРОС');assert.match(await page.locator('#scenario-objective').textContent(),/4 ПРЯМЫХ ОТВЕТА/);assert.match(await page.locator('#scenario-objective').textContent(),/CONTACT ≥50/);assert.equal(await page.locator('#opponent-card').getAttribute('data-preset'),'DIRECT_ANSWER');await page.locator('[data-scenario=\"contact\"]').click();assert.equal(await page.locator('#scenario-title').textContent(),'КРИТИКА ИДЕИ');assert.ok((await page.locator('#opponent-name').textContent()).trim().length>0);const opponentCharacter=await page.locator('#opponent-card').getAttribute('data-character');"
